import os, sys
sys.path.insert(0, os.path.dirname(__file__))
from presets_data import PRESETS

out = ['#pragma once', '#include "Params.h"', '',
       '// Generated by tools/gen_presets_header.py. Edit tools/presets_data.py, then regenerate.',
       'namespace vh', '{', 'struct Preset { const char* name; float v[kNumFloat]; bool sync; int division; };', '',
       'inline const Preset kPresets[] =', '{']
for name, vals, sync, div, _ in PRESETS:
    nums = ', '.join((f'{float(v):g}' if ('.' in f'{float(v):g}') else f'{float(v):g}.0') + 'f' for v in vals)
    out.append(f'    {{ "{name}", {{ {nums} }}, {"true" if sync else "false"}, {div} }},')
out += ['};', 'inline constexpr int kNumPresets = (int) (sizeof (kPresets) / sizeof (kPresets[0]));', '} // namespace vh', '']
open(os.path.join(os.path.dirname(__file__), '..', 'Source', 'Presets.h'), 'w').write('\n'.join(out))
print('ok')
